import json
from typing import Any, Dict, Tuple, Optional, List

import jax
import jax.numpy as jnp
from jax import random as jr
import flax.linen as nn
import optax

# Minimal stubs to satisfy loader (unused by test())
class _NullNet(nn.Module):
    @nn.compact
    def __call__(self, x, done, rnn_state=None):
        B = x.shape[0]
        z = x.reshape((B, -1))
        h = nn.Dense(16, kernel_init=nn.initializers.xavier_uniform())(z)
        h = nn.relu(h)
        policy_logits = nn.Dense(4, kernel_init=nn.initializers.xavier_uniform())(h)
        value = nn.Dense(1, kernel_init=nn.initializers.xavier_uniform())(h).squeeze(-1)
        return policy_logits, value, {"h": jnp.zeros((B,))}

def create_network(hparams: Dict[str, Any] = None):
    return _NullNet()

def create_optimizer(learning_rate: float = 4e-4):
    return optax.adam(learning_rate)

# PG backbone for features (same as v1; kernel_dilation used)
class BottleneckDilatedBlock(nn.Module):
    features: int
    bottleneck_ratio: float = 0.28
    dilation: int = 6
    @nn.compact
    def __call__(self, x):
        mid = max(1, int(self.features * self.bottleneck_ratio))
        y = nn.Conv(mid, (1,1), padding='SAME',
                    kernel_init=nn.initializers.xavier_uniform())(x)
        y = nn.relu(y)
        y = nn.Conv(mid, (3,3), padding='SAME',
                    kernel_dilation=(self.dilation, self.dilation),
                    kernel_init=nn.initializers.xavier_uniform())(y)
        y = nn.relu(y)
        y = nn.Conv(self.features, (1,1), padding='SAME',
                    kernel_init=nn.initializers.xavier_uniform())(y)
        return nn.relu(x + y)

class ConvLSTMCellLN(nn.Module):
    features: int
    kernel_size: Tuple[int,int] = (3,3)
    @nn.compact
    def __call__(self, carry, x):
        h, c = carry
        gates_lin = nn.Conv(4*self.features, self.kernel_size, padding='SAME',
                            kernel_init=nn.initializers.xavier_uniform())(
            jnp.concatenate([x, h], axis=-1))
        gates_ln = nn.LayerNorm(epsilon=1e-5)(gates_lin)
        i_lin, f_lin, g_lin, o_lin = jnp.split(gates_ln, 4, axis=-1)
        i = jax.nn.sigmoid(i_lin); f = jax.nn.sigmoid(f_lin); o = jax.nn.sigmoid(o_lin); g = jnp.tanh(g_lin)
        c = f * c + i * g
        h = o * jnp.tanh(c)
        gates = {"i_lin": i_lin, "f_lin": f_lin, "g_lin": g_lin, "o_lin": o_lin}
        return (h, c), h, gates

class FeatureExtractor(nn.Module):
    cnn1: int = 32
    cnn2: int = 64
    convlstm: int = 64
    dilation: int = 6
    bottleneck_ratio: float = 0.28
    @nn.compact
    def __call__(self, x, done, rnn_state=None):
        B = x.shape[0]
        x = nn.Conv(self.cnn1, (3,3), padding='SAME',
                    kernel_init=nn.initializers.xavier_uniform())(x); x = nn.relu(x)
        x = BottleneckDilatedBlock(self.cnn1, self.bottleneck_ratio, self.dilation)(x)
        x = nn.Conv(self.cnn2, (3,3), padding='SAME',
                    kernel_init=nn.initializers.xavier_uniform())(x); x = nn.relu(x)
        x = BottleneckDilatedBlock(self.cnn2, self.bottleneck_ratio, self.dilation)(x)
        if rnn_state is None:
            zeros = lambda: jnp.zeros((B, 8, 8, self.convlstm), dtype=x.dtype)
            rnn_state = {'h': zeros(), 'c': zeros()}
        if done is not None:
            m = (1.0 - done.reshape(B,1,1,1).astype(x.dtype))
            rnn_state = {'h': rnn_state['h'] * m, 'c': rnn_state['c'] * m}
        (h_new, c_new), h_out, gates = ConvLSTMCellLN(self.convlstm)((rnn_state['h'], rnn_state['c']), x)
        rnn_state = {'h': h_new, 'c': c_new}
        return h_out, gates, rnn_state

def attn_pool(h_out):
    B,H,W,C = h_out.shape
    logits = nn.Conv(1, (1,1), padding='SAME',
                     kernel_init=nn.initializers.xavier_uniform())(h_out).reshape((B, H*W))
    weights = jax.nn.softmax(logits, axis=-1).reshape((B, H*W, 1))
    tokens = h_out.reshape((B, H*W, C))
    attn_vec = (weights * tokens).sum(axis=1)   # (B,C)
    return attn_vec, weights  # (B,C), (B,64,1)

# Head-only readouts (operate on z)
class DualHeadReadout(nn.Module):
    head_hidden: int = 64
    @nn.compact
    def __call__(self, z):  # z: (B,2C)
        shared = nn.Dense(256, kernel_init=nn.initializers.xavier_uniform())(z); shared = nn.relu(shared)
        ph = nn.Dense(self.head_hidden, kernel_init=nn.initializers.xavier_uniform())(shared); ph = nn.relu(ph)
        policy_logits = nn.Dense(4, kernel_init=nn.initializers.xavier_uniform())(ph)
        vh = nn.Dense(self.head_hidden, kernel_init=nn.initializers.xavier_uniform())(shared); vh = nn.relu(vh)
        value = nn.Dense(1, kernel_init=nn.initializers.xavier_uniform())(vh).squeeze(-1)
        return policy_logits, value

class SimpleHeadReadout(nn.Module):
    @nn.compact
    def __call__(self, z):  # z: (B,C)
        shared = nn.Dense(256, kernel_init=nn.initializers.xavier_uniform())(z); shared = nn.relu(shared)
        policy_logits = nn.Dense(4, kernel_init=nn.initializers.xavier_uniform())(shared)
        value = nn.Dense(1, kernel_init=nn.initializers.xavier_uniform())(shared).squeeze(-1)
        return policy_logits, value

class GapOnlyReadout(nn.Module):
    @nn.compact
    def __call__(self, z):  # z: (B,C)
        shared = nn.Dense(256, kernel_init=nn.initializers.xavier_uniform())(z); shared = nn.relu(shared)
        policy_logits = nn.Dense(4, kernel_init=nn.initializers.xavier_uniform())(shared)
        value = nn.Dense(1, kernel_init=nn.initializers.xavier_uniform())(shared).squeeze(-1)
        return policy_logits, value

