def generate_synth(key, B=32):
    k1, k2, k3 = jr.split(key, 3)
    labels = jr.randint(k1, (B, 8, 8), 0, 7)
    oh = jax.nn.one_hot(labels, 7)  # (B,8,8,7)
    noise_mask = jr.bernoulli(k2, 0.10, (B,8,8,1))
    noise_lbl = jr.randint(k3, (B,8,8), 0, 7)
