    if w is None:
        return None
    w = w.squeeze(-1)
    eps = 1e-8
    H = -jnp.sum(w * jnp.log(jnp.clip(w, eps, 1.0)), axis=1)
    topk = jnp.sort(w, axis=1)[:, -k:]
    topk_mass = jnp.sum(topk, axis=1)
    return {"entropy_mean": float(jnp.mean(H)),
            "entropy_std": float(jnp.std(H)),
            "top5_mass_mean": float(jnp.mean(topk_mass))}

