        return jnp.mean((jnp.abs(jnp.tanh(x)) > 0.9).astype(jnp.float32))
    out = {}
    for name in ["i_lin","f_lin","o_lin","g_lin"]:
        x = gates[name]
        if name == "g_lin":
            out["g"] = {"mean": float(jnp.mean(x)), "std": float(jnp.std(x)), "sat": float(_sat_tanh(x))}
        else:
            lo, hi = _sat_sig(x)
            out[name[0]] = {"mean": float(jnp.mean(x)), "std": float(jnp.std(x)),
                            "sat_low": float(lo), "sat_high": float(hi)}
    return out

