        v = jnp.ones((W.shape[1],), dtype=W.dtype)
        v = v / (jnp.linalg.norm(v) + 1e-8)
        for _ in range(iters):
            v = W.T @ (W @ v)
            v = v / (jnp.linalg.norm(v) + 1e-8)
        return jnp.linalg.norm(W @ v)
    def _walk(d):
        for k,v in d.items():
            if isinstance(v, dict):
                if 'kernel' in v and isinstance(v['kernel'], jnp.ndarray) and v['kernel'].ndim == 2:
                    specs.append(float(_power_iter(v['kernel'], iters)))
                _walk(v)
