    if not specs:
        return {"dense_spec_max": None, "dense_spec_mean": None}
    arr = jnp.array(specs)
    return {"dense_spec_max": float(jnp.max(arr)), "dense_spec_mean": float(jnp.mean(arr))}

def grad_z_norm(model, variables, z):
    def f(inp):
        logits, _ = model.apply(variables, inp)
        return jnp.sum(logits)
    g = jax.grad(f)(z)
    l2 = jnp.sqrt(jnp.sum(g*g, axis=1))  # per-sample
    z_l2 = jnp.sqrt(jnp.sum(z*z, axis=1)) + 1e-8
    return float(jnp.mean(l2)), float(jnp.mean(l2 / z_l2))  # absolute and normalized

def run_v2(key):
    # Step 1: build features and z variants from shared backbone
    B = 32
    x, done = generate_synth(key, B=B)
    feat = FeatureExtractor()
    fvars = feat.init(jr.fold_in(key, 0), x, done, None)
    h_out, gates, _ = feat.apply(fvars, x, done, None)
    attn_vec, attn_w = attn_pool(h_out)
    gap_vec = h_out.mean(axis=(1,2))
    z_dual = jnp.concatenate([attn_vec, gap_vec], axis=-1)  # (B, 2C)
    z_attn = attn_vec  # (B, C)
    z_gap  = gap_vec   # (B, C)

    # Step 2: head-only readouts (initialized independently; curvature at init)
    dual = DualHeadReadout(head_hidden=64)
    simp = SimpleHeadReadout()
    gap  = GapOnlyReadout()

    dvars = dual.init(jr.fold_in(key, 101), z_dual)
    svars = simp.init(jr.fold_in(key, 102), z_attn)
    gvars = gap.init(jr.fold_in(key, 103), z_gap)

    # Spectral norms
    d_spec = spectral_norms(dvars.get("params", {}))
    s_spec = spectral_norms(svars.get("params", {}))
    g_spec = spectral_norms(gvars.get("params", {}))

    # z→logits gradient norms (absolute and normalized by ||z||)
    d_g_abs, d_g_rel = grad_z_norm(dual, dvars, z_dual)
    s_g_abs, s_g_rel = grad_z_norm(simp, svars, z_attn)
    g_g_abs, g_g_rel = grad_z_norm(gap,  gvars, z_gap)

    # Attention and gate stats (from shared backbone)
    a_stats = attn_entropy_topk(attn_w)
    g_stats = gate_stats(gates)

    return {
        "seed": 42,
        "batch": [B, 8, 8, 8],
        "z_dims": {"dual": int(z_dual.shape[1]), "simple": int(z_attn.shape[1]), "gap": int(z_gap.shape[1])},
        "models": {
            "dual_attn_gap_deep": {
                "z_grad_l2_mean": d_g_abs, "z_grad_rel_mean": d_g_rel, "dense_spectral_norm": d_spec
            },
            "simple_head_attn": {
                "z_grad_l2_mean": s_g_abs, "z_grad_rel_mean": s_g_rel, "dense_spectral_norm": s_spec
            },
            "gap_only_head": {
                "z_grad_l2_mean": g_g_abs, "z_grad_rel_mean": g_g_rel, "dense_spectral_norm": g_spec
            }
        },
        "attn": a_stats if a_stats is not None else "n/a",
        "gate_stats": g_stats
    }

def test():
    out = run_v2(jr.PRNGKey(42))
    print(json.dumps(out, indent=2))
    return "OK"

